import java.util.Scanner;

public class Main {
    static long[] f = new long[18];

    static int Solve(long x) {
        int res, digits = 15;
        if (x <= 11L) return (int) Math.min(x, 13 - x);
        while (f[digits] >= x) --digits;
        res = (int) ((x / f[digits]) * digits) + Solve(x % f[digits]);
        if ((x << 1) < f[digits + 1]) return res;
        return Math.min(res, digits + Solve(f[digits + 1] - x) + 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        f[1] = 1;
        for (int i = 2; i <= 16; ++i) {
            f[i] = f[i - 1] * 10 + 1;
        }
        long n = sc.nextLong();
        System.out.println(Solve(n));
        sc.close();
    }
}
